3D poster card showcase. 16s, 1920x1080, SILENT. Card 580x870px. Colored background per card. Role name top-right corner of screen (not below card). Card has pulsing box-shadow glow on the card-face element directly. Specular sweep. Rocking motion via GSAP
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;}
#scene{position:relative;display:flex;align-items:center;justify-content:center;}
bg-panel{position:absolute;inset:0;opacity:0;}
#bg1{background:radial-gradient(ellipse at 50% 40%,#3a2800 0%,#1a1000 55%,#080500 100%);}
#bg2{background:radial-gradient(ellipse at 50% 40%,#001435 0%,#000a22 55%,#000308 100%);}
#bg3{background:radial-gradient(ellipse at 50% 40%,#2a0008 0%,#180005 55%,#080002 100%);}
/* ambient glow disk behind card */
glow-disk{
position:absolute
width:720px;height:960px
border-radius:50%
filter:blur(110px)
opacity:0;z-index:1
}
card-stage{
position:absolute;z-index:5
display:flex;align-items:center;justify-content:center
opacity:0;width:100%;height:100%
}
card-wrap{
width:580px;height:870px
position:relative;z-index:2;flex-shrink:0
}
/* card-face: glow is applied here with animation */
card-face{
width:100%;height:100%
border-radius:10px;overflow:hidden;position:relative
}
card-face img{
width:100%;height:100%
object-fit:cover;object-position:center top;display:block
}
card-face::after{
content:""
position:absolute;top:0;left:-70%
width:42%;height:100%
background:linear-gradient(108deg,transparent 28%,rgba(255,255,255,0.14) 50%,transparent 72%)
animation:spec 2.4s ease-in-out infinite alternate
pointer-events:none;z-index:2
}
@keyframes spec{from{left:-70%;}to{left:120%;}}
/* glow animations directly on .card-face */
#s1 .card-face{animation:gA 1.8s ease-in-out infinite alternate;}
@keyframes gA{
from{box-shadow:0 0 20px 4px rgba(255,160,20,0.30),0 0 60px 10px rgba(255,130,0,0.18),0 30px 80px rgba(0,0,0,0.90);}
to  {box-shadow:0 0 50px 12px rgba(255,200,60,0.60),0 0 120px 30px rgba(255,160,30,0.42),0 30px 80px rgba(0,0,0,0.90);}
}
#s1 .glow-disk{background:radial-gradient(ellipse,rgba(255,140,20,0.48),transparent 70%);}
#s2 .card-face{animation:gB 1.8s ease-in-out infinite alternate;}
@keyframes gB{
from{box-shadow:0 0 20px 4px rgba(40,120,255,0.30),0 0 60px 10px rgba(20,90,240,0.18),0 30px 80px rgba(0,0,0,0.90);}
to  {box-shadow:0 0 50px 12px rgba(80,170,255,0.60),0 0 120px 30px rgba(50,130,255,0.42),0 30px 80px rgba(0,0,0,0.90);}
}
#s2 .glow-disk{background:radial-gradient(ellipse,rgba(30,100,255,0.44),transparent 70%);}
#s3 .card-face{animation:gC 1.8s ease-in-out infinite alternate;}
@keyframes gC{
from{box-shadow:0 0 20px 4px rgba(200,30,30,0.30),0 0 60px 10px rgba(170,10,10,0.18),0 30px 80px rgba(0,0,0,0.90);}
to  {box-shadow:0 0 50px 12px rgba(255,60,60,0.60),0 0 120px 30px rgba(220,30,30,0.42),0 30px 80px rgba(0,0,0,0.90);}
}
#s3 .glow-disk{background:radial-gradient(ellipse,rgba(180,20,20,0.44),transparent 70%);}
/* role name — top-right corner */
role-label{
position:absolute
top:72px;right:88px
z-index:20
text-align:right
opacity:0
}
role-name{
font-family:'Playfair Display',Georgia,serif
font-size:52px;font-weight:700
color:#f0ece4;line-height:.90;letter-spacing:-.01em
text-shadow:0 2px 20px rgba(0,0,0,0.70)
}
#open-fade,#close-fade{position:absolute;inset:0;z-index:50;background:#000;pointer-events:none;}
#open-fade{opacity:1;}#close-fade{opacity:0;}
</style>
</head>
<body>
<div id="scene">
<div id="bg1" class="bg-panel"></div>
<div id="bg2" class="bg-panel"></div>
<div id="bg3" class="bg-panel"></div>
<div id="open-fade"></div>
<div id="close-fade"></div>
<div class="card-stage" id="s1">
<div class="glow-disk"></div>
<div class="card-wrap" id="w1"><div class="card-face"><img src="{{p1}}" alt=""></div></div>
<div class="role-label" id="l1"><div class="role-name">Alan Turing</div></div>
</div>
<div class="card-stage" id="s2">
<div class="glow-disk"></div>
<div class="card-wrap" id="w2"><div class="card-face"><img src="{{p2}}" alt=""></div></div>
<div class="role-label" id="l2"><div class="role-name">Sherlock Holmes</div></div>
</div>
<div class="card-stage" id="s3">
<div class="glow-disk"></div>
<div class="card-wrap" id="w3"><div class="card-face"><img src="{{p3}}" alt=""></div></div>
<div class="role-label" id="l3"><div class="role-name">Hamlet</div></div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
function rock(el){
gsap.set(el,{transformPerspective:1100,rotateX:3.5,rotateY:-16})
gsap.to(el,{rotateY:16,rotateX:2,duration:1.25,ease:'sine.inOut',repeat:-1,yoyo:true})
}
var tl=gsap.timeline()
tl.to('#open-fade',{opacity:0,duration:0.4,ease:'power2.out'},0.0)
/* card 1 */
tl.to('#bg1',{opacity:1,duration:0.55,ease:'power2.out'},0.35)
tl.set('#s1',{opacity:1},0.4)
tl.to('#s1 .glow-disk',{opacity:1,duration:0.55},0.4)
tl.to('#s1 .card-wrap',{scale:1,duration:0.7,ease:'back.out(1.2)',startAt:{scale:0.75}},0.4)
tl.to('#l1',{opacity:1,duration:0.4,ease:'power2.out'},0.8)
tl.call(function(){rock(document.querySelector('#w1'));},null,0.4)
tl.to(['#s1 .glow-disk','#l1'],{opacity:0,duration:0.3},4.5)
tl.to('#bg1',{opacity:0,duration:0.35},4.5)
tl.to('#s1 .card-wrap',{scale:0.80,duration:0.38,ease:'power2.in'},4.5)
tl.to('#s1',{opacity:0,duration:0.3},4.55)
tl.call(function(){gsap.killTweensOf('#w1');},null,4.9)
tl.set('#s1',{opacity:0},4.95)
/* card 2 */
tl.to('#bg2',{opacity:1,duration:0.55,ease:'power2.out'},4.85)
tl.set('#s2',{opacity:1},4.9)
tl.to('#s2 .glow-disk',{opacity:1,duration:0.55},4.9)
tl.to('#s2 .card-wrap',{scale:1,duration:0.7,ease:'back.out(1.2)',startAt:{scale:0.75}},4.9)
tl.to('#l2',{opacity:1,duration:0.4,ease:'power2.out'},5.3)
tl.call(function(){rock(document.querySelector('#w2'));},null,4.9)
tl.to(['#s2 .glow-disk','#l2'],{opacity:0,duration:0.3},9.5)
tl.to('#bg2',{opacity:0,duration:0.35},9.5)
tl.to('#s2 .card-wrap',{scale:0.80,duration:0.38,ease:'power2.in'},9.5)
tl.to('#s2',{opacity:0,duration:0.3},9.55)
tl.call(function(){gsap.killTweensOf('#w2');},null,9.9)
tl.set('#s2',{opacity:0},9.95)
/* card 3 */
tl.to('#bg3',{opacity:1,duration:0.55,ease:'power2.out'},9.85)
tl.set('#s3',{opacity:1},9.9)
tl.to('#s3 .glow-disk',{opacity:1,duration:0.55},9.9)
tl.to('#s3 .card-wrap',{scale:1,duration:0.7,ease:'back.out(1.2)',startAt:{scale:0.75}},9.9)
tl.to('#l3',{opacity:1,duration:0.4,ease:'power2.out'},10.3)
tl.call(function(){rock(document.querySelector('#w3'));},null,9.9)
tl.to(['#s3 .glow-disk','#l3'],{opacity:0,duration:0.3},14.5)
tl.to('#bg3',{opacity:0,duration:0.35},14.5)
tl.to('#s3 .card-wrap',{scale:0.80,duration:0.38,ease:'power2.in'},14.5)
tl.to('#close-fade',{opacity:1,duration:0.6,ease:'power2.inOut'},14.7)
tl.set('#close-fade',{opacity:1},15.4)
})
</script>
</body>
</html>
```
